mapper.select:
select id, title, kind, status, updated_at
from (
    select id, title, 'COURSE' kind, status, updated_at from courses
    union all
    select id, name title, 'EXERCISE' kind, status, updated_at from exercises
) content
order by updated_at desc
limit #{limit}

select count(*)
from users
where phone = #{phone} and id != #{id}

mapper.update:
update auth_sessions
set revoked_at = #{now}
where user_id = #{userId} and revoked_at is null

mapper.select:
select count(*) from courses

    lower(title) like concat('%', lower(#{query}), '%')
    and status = #{status}

select * from courses

    lower(title) like concat('%', lower(#{query}), '%')
    and status = #{status}

order by sort_order, updated_at desc
limit #{limit} offset #{offset}

select count(*) from exercises

    lower(name) like concat('%', lower(#{query}), '%')
    and status = #{status}

select * from exercises

    lower(name) like concat('%', lower(#{query}), '%')
    and status = #{status}

order by sort_order, updated_at desc
limit #{limit} offset #{offset}

select c.*, count(cc.id) checkin_count from campaigns c left join campaign_checkins cc on cc.campaign_code = c.code
lower(c.title) like concat('%', lower(#{query}), '%') or lower(c.code) like concat('%', lower(#{query}), '%')
group by c.id, c.code, c.title, c.rules_text, c.start_date, c.end_date, c.status, c.sort_order, c.created_at, c.updated_at order by c.sort_order, c.updated_at desc limit #{limit} offset #{offset}

mapper.update:
update campaigns
set code = upper(replace(replace(trim(#{request.code}), '-', '_'), ' ', '_')),
    title = trim(#{request.title}), rules_text = trim(#{request.rulesText}),
    start_date = #{request.startDate}, end_date = #{request.endDate}, status = #{request.status},
    sort_order = #{request.sortOrder}
where id = #{id}

mapper.select:
select w.id, w.user_id, coalesce(u.nickname, concat('用户 ', u.id)) user_name, w.course_id, c.title course_title, w.duration_minutes, w.completion_percent, w.started_at, w.completed_at from workout_records w join users u on u.id = w.user_id join courses c on c.id = w.course_id
lower(coalesce(u.nickname, '')) like concat('%', lower(#{query}), '%') or lower(c.title) like concat('%', lower(#{query}), '%')
order by w.completed_at desc limit #{limit} offset #{offset}

mapper.update:
update device_models
set name = trim(#{request.name}), brand = #{request.brand}, sn_prefix = upper(trim(#{request.snPrefix}))
where id = #{id}
